// Factory-owned acceptance tests for bonus-library-reading-time, generated from its approved idea.
// The builder must make these pass and cannot edit them.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';
import * as m0 from "../../src/lib/reading-time.ts";

const source = (path) => readFileSync(new URL('../../' + path, import.meta.url), 'utf8');

test("1. src/lib/reading-time.ts exports WORDS_PER_MINUTE, readingMinutes, formatReadingTime", async () => {
  assert.notEqual(m0["WORDS_PER_MINUTE"], undefined, "WORDS_PER_MINUTE");
  assert.notEqual(m0["readingMinutes"], undefined, "readingMinutes");
  assert.notEqual(m0["formatReadingTime"], undefined, "formatReadingTime");
});

test("2. readingMinutes(\"\") returns 1", async () => {
  assert.equal(typeof m0.readingMinutes, 'function');
  assert.deepEqual(await m0.readingMinutes(...[""]), 1);
});

test("3. readingMinutes(\"   \\n\\t \") returns 1", async () => {
  assert.equal(typeof m0.readingMinutes, 'function');
  assert.deepEqual(await m0.readingMinutes(...["   \n\t "]), 1);
});

test("4. readingMinutes(\"one two three\") returns 1", async () => {
  assert.equal(typeof m0.readingMinutes, 'function');
  assert.deepEqual(await m0.readingMinutes(...["one two three"]), 1);
});

test("5. readingMinutes(\"word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word w", async () => {
  assert.equal(typeof m0.readingMinutes, 'function');
  assert.deepEqual(await m0.readingMinutes(...["word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word"]), 2);
});

test("6. formatReadingTime(3) returns \"3 min read\"", async () => {
  assert.equal(typeof m0.formatReadingTime, 'function');
  assert.deepEqual(await m0.formatReadingTime(...[3]), "3 min read");
});

test("7. formatReadingTime(0) returns \"1 min read\"", async () => {
  assert.equal(typeof m0.formatReadingTime, 'function');
  assert.deepEqual(await m0.formatReadingTime(...[0]), "1 min read");
});

test("8. formatReadingTime(2.5) returns \"1 min read\"", async () => {
  assert.equal(typeof m0.formatReadingTime, 'function');
  assert.deepEqual(await m0.formatReadingTime(...[2.5]), "1 min read");
});

test("9. src/lib/reading-time.ts does not contain \"import \"", async () => {
  assert.equal(source("src/lib/reading-time.ts").includes("import "), false);
});
